    for (int i = 0; i < n; i++) {
      xy[2 * i] = pts[i].x;
      xy[2 * i + 1] = pts[i].y;
    }
    stroke_polyline(dpy->canvas, gc, xy, n, 0);
    if (xy != stack_xy) free(xy);
    return 0;
  }
  for (int i = 1; i < n; i++)
    XDrawLine(dpy, d, gc, pts[i - 1].x, pts[i - 1].y, pts[i].x, pts[i].y);
  return 0;
}

