  const double q[4] = {*x1 - xmin, xmax - *x1, *y1 - ymin, ymax - *y1};
  double t0 = 0, t1 = 1;
  for (int i = 0; i < 4; i++) {
    if (p[i] == 0) {
      if (q[i] < 0) return 0;
    } else {
      const double t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return 0;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return 0;
        if (t < t1) t1 = t;
      }
    }
  }
  const double ax = *x1 + t0 * dx, ay = *y1 + t0 * dy;
  const double bx = *x1 + t1 * dx, by = *y1 + t1 * dy;
  *x1 = ax;
  *y1 = ay;
  *x2 = bx;
  *y2 = by;
