static int clipped_out(const GC gc, int64_t x, int64_t y) {
  if (!gc->clip) return 0;
  const int64_t mx = x - gc->clip_x, my = y - gc->clip_y;
  if (mx < 0 || my < 0 || mx >= gc->clip->w || my >= gc->clip->h) return 1;
  return !bit_at(gc->clip, (int)mx, (int)my);
}

static int64_t min64(int64_t a, int64_t b) { return a < b ? a : b; }
static int64_t max64(int64_t a, int64_t b) { return a > b ? a : b; }

/* The largest pixmap XCreatePixmap will make: 4 million pixels, which is 8 MB
 * of RGB565, more than the board has. */
#define MAX_PIXMAP_PIXELS 4000000ULL

Pixmap XCreatePixmap(Display *dpy, Drawable d, unsigned int w, unsigned int h,
                     unsigned int depth) {
  (void)dpy, (void)d;
  if (w == 0 || h == 0 || (uint64_t)w * h > MAX_PIXMAP_PIXELS) return None;
  struct XshimPixmap *pm = pixmap_new((int)w, (int)h, depth == 1 ? 1 : 16);
  if (!pm) return None;
  if (pm->bits)
    memset(pm->bits, 0, (size_t)pm->stride * (size_t)pm->h);
  else
    memset(pm->rgb, 0, (size_t)pm->w * (size_t)pm->h * sizeof(uint16_t));
  return (Pixmap)(uintptr_t)pm;
}

static void set_bit(struct XshimPixmap *pm, int x, int y, int on) {
  uint8_t *byte = &pm->bits[y * pm->stride + x / 8];
  const uint8_t mask = (uint8_t)(0x80 >> (x % 8));
  *byte = on ? (uint8_t)(*byte | mask) : (uint8_t)(*byte & ~mask);
}

/* Copies the part of the rectangle that lies inside both the source and the
 * destination (a pixmap, or the canvas when dst is NULL), so a huge width or
 * height costs nothing. All sums are in 64 bits. Between a colour source and a
 * colour destination, or two bitmaps, pixels are copied as they are; a bitmap
 * drawn on the canvas uses the GC's foreground and background. When source and
 * destination are the same pixmap and overlap, rows and columns are walked in
 * the order that reads each pixel before it is overwritten. */
static void copy_region(Display *dpy, GC gc, const struct XshimPixmap *src,
                        struct XshimPixmap *dst, int sx, int sy,
                        unsigned int w, unsigned int h, int dx, int dy) {
  const int64_t dw = dst ? dst->w : dpy->canvas->w;
  const int64_t dh = dst ? dst->h : dpy->canvas->h;
  const int64_t i0 = max64(0, max64(-(int64_t)sx, -(int64_t)dx));
  const int64_t i1 = min64(w, min64((int64_t)src->w - sx, dw - dx));
  const int64_t j0 = max64(0, max64(-(int64_t)sy, -(int64_t)dy));
  const int64_t j1 = min64(h, min64((int64_t)src->h - sy, dh - dy));
  const int same = dst == src;
  const int reverse_x = same && dx > sx, reverse_y = same && dy > sy;
  for (int64_t jj = 0; jj < j1 - j0; jj++) {
    const int64_t j = reverse_y ? j1 - 1 - jj : j0 + jj;
    for (int64_t ii = 0; ii < i1 - i0; ii++) {
      const int64_t i = reverse_x ? i1 - 1 - ii : i0 + ii;
      const int64_t x = dx + i, y = dy + j;
      if (clipped_out(gc, x, y)) continue;
      const int64_t px = sx + i, py = sy + j;
      if (src->depth == 1) {
        const int bit = bit_at(src, (int)px, (int)py);
        if (!dst)
          canvas_point(dpy->canvas, (int)x, (int)y,
                       (uint16_t)(bit ? gc->foreground : gc->background));
        else
          set_bit(dst, (int)x, (int)y, bit);
      } else {
        const uint16_t colour = src->rgb[py * src->w + px];
        if (!dst)
          canvas_point(dpy->canvas, (int)x, (int)y, colour);
        else
          dst->rgb[y * dst->w + x] = colour;
      }
    }
  }
}

/* To the canvas, the source must be a colour pixmap. To a pixmap, source and
 * destination must have the same depth. Anything else draws nothing. */
int XCopyArea(Display *dpy, Drawable src, Drawable dst, GC gc, int sx, int sy,
              unsigned int w, unsigned int h, int dx, int dy) {
  const struct XshimPixmap *pm = pixmap_of(src);
  struct XshimPixmap *target = pixmap_of(dst);
  if (!pm) return 0;
  if (target ? pm->depth == target->depth : pm->depth == 16)
    copy_region(dpy, gc, pm, target, sx, sy, w, h, dx, dy);
  return 0;
}

/* Always draws on the canvas, whatever dst is. */
int XCopyPlane(Display *dpy, Drawable src, Drawable dst, GC gc, int sx,
               int sy, unsigned int w, unsigned int h, int dx, int dy,
               unsigned long plane) {
  (void)dst;
  const struct XshimPixmap *pm = pixmap_of(src);
  if (pm && pm->depth == 1 && plane == 1)
    copy_region(dpy, gc, pm, NULL, sx, sy, w, h, dx, dy);
  return 0;
}

int XSync(Display *dpy, Bool discard) {
  (void)dpy, (void)discard;
  return 0;
}

#include "core/canvas.h"

#include <math.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

/* The ESP32 has a 32-bit long; clip arithmetic needs 64 bits to be safe. */
typedef int64_t wide_t;

static void mark_all_dirty(Canvas *c) {
  for (int y = 0; y < c->h; y++) {
    c->dirty_x0[y] = 0;
    c->dirty_x1[y] = (int16_t)(c->w - 1);
  }
}

/* The caller has already clipped x0..x1 and y to the canvas. */
static inline void mark_span(Canvas *c, wide_t x0, wide_t x1, wide_t y) {
  if (x0 < c->dirty_x0[y]) c->dirty_x0[y] = (int16_t)x0;
  if (x1 > c->dirty_x1[y]) c->dirty_x1[y] = (int16_t)x1;
}

int canvas_init(Canvas *c, int w, int h, void *(*alloc)(size_t)) {
  c->w = w;
  c->h = h;
  c->px = NULL;
  c->dirty_x0 = c->dirty_x1 = NULL;
  /* The dirty spans are int16_t. */
  if (w <= 0 || h <= 0 || w > INT16_MAX || h > INT16_MAX) return -1;
  c->px = (uint16_t *)alloc((size_t)w * (size_t)h * sizeof(uint16_t));
  if (!c->px) return -1;
  memset(c->px, 0, (size_t)w * (size_t)h * sizeof(uint16_t));
  c->dirty_x0 = (int16_t *)malloc((size_t)h * sizeof(int16_t));
  c->dirty_x1 = (int16_t *)malloc((size_t)h * sizeof(int16_t));
  if (!c->dirty_x0 || !c->dirty_x1) {
    canvas_free(c);
    return -1;
  }
  mark_all_dirty(c);
  return 0;
}

void canvas_free(Canvas *c) {
  free(c->px);
  free(c->dirty_x0);
  free(c->dirty_x1);
  c->px = NULL;
  c->dirty_x0 = c->dirty_x1 = NULL;
}

uint16_t px_swap(uint16_t v) { return (uint16_t)((v << 8) | (v >> 8)); }

uint16_t rgb565(uint8_t r, uint8_t g, uint8_t b) {
  return px_swap((uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3)));
}

uint16_t rgb565_from16(uint16_t r, uint16_t g, uint16_t b) {
  return rgb565((uint8_t)(r >> 8), (uint8_t)(g >> 8), (uint8_t)(b >> 8));
}

bool canvas_dirty_row(const Canvas *c, int y, int *x0, int *x1) {
  if (y < 0 || y >= c->h || c->dirty_x0[y] > c->dirty_x1[y]) return false;
  *x0 = c->dirty_x0[y];
  *x1 = c->dirty_x1[y];
  return true;
}

void canvas_clear_dirty(Canvas *c) {
  for (int y = 0; y < c->h; y++) {
    c->dirty_x0[y] = (int16_t)c->w;
    c->dirty_x1[y] = -1;
  }
}

void canvas_clear(Canvas *c, uint16_t color) {
  for (int i = 0, n = c->w * c->h; i < n; i++) c->px[i] = color;
  mark_all_dirty(c);
}

void canvas_point(Canvas *c, int x, int y, uint16_t color) {
  if (x < 0 || y < 0 || x >= c->w || y >= c->h) return;
  c->px[(size_t)y * c->w + x] = color;
  mark_span(c, x, x, y);
}

static void hspan(Canvas *c, wide_t x0, wide_t x1, wide_t y, uint16_t color) {
  if (y < 0 || y >= c->h || x1 < 0 || x0 >= c->w) return;
  if (x0 < 0) x0 = 0;
  if (x1 >= c->w) x1 = c->w - 1;
  if (x0 > x1) return;
  mark_span(c, x0, x1, y);
  uint16_t *row = c->px + (size_t)y * c->w;
  for (int x = (int)x0, last = (int)x1; x <= last; x++) row[x] = color;
}

void canvas_fill_rect(Canvas *c, int x, int y, int w, int h, uint16_t color) {
  if (w <= 0 || h <= 0) return;
  wide_t x1 = (wide_t)x + w - 1, y1 = (wide_t)y + h - 1;
  wide_t y0 = y < 0 ? 0 : y;
  if (y1 >= c->h) y1 = c->h - 1;
  for (wide_t yy = y0; yy <= y1; yy++) hspan(c, x, x1, yy, color);
}

/* Liang-Barsky clip of the segment to [0,w-1]x[0,h-1]; false if outside. */
static int clip_line(const Canvas *c, double *x0, double *y0, double *x1,
                     double *y1) {
  double dx = *x1 - *x0, dy = *y1 - *y0, t0 = 0, t1 = 1;
  double p[4] = {-dx, dx, -dy, dy};
  double q[4] = {*x0, (c->w - 1) - *x0, *y0, (c->h - 1) - *y0};
  for (int i = 0; i < 4; i++) {
    if (p[i] == 0) {
      if (q[i] < 0) return 0;
    } else {
      double t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return 0;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return 0;
        if (t < t1) t1 = t;
      }
    }
  }
  double ax = *x0, ay = *y0;
  *x0 = ax + t0 * dx;
  *y0 = ay + t0 * dy;
  *x1 = ax + t1 * dx;
  *y1 = ay + t1 * dy;
  return 1;
}

void canvas_line(Canvas *c, int x0, int y0, int x1, int y1, uint16_t color) {
  double ax = x0, ay = y0, bx = x1, by = y1;
  int clipped = x0 < 0 || y0 < 0 || x0 >= c->w || y0 >= c->h || x1 < 0 ||
                y1 < 0 || x1 >= c->w || y1 >= c->h;
  if (clipped) {
    if (!clip_line(c, &ax, &ay, &bx, &by)) return;
    ax = floor(ax + 0.5);
    ay = floor(ay + 0.5);
    bx = floor(bx + 0.5);
    by = floor(by + 0.5);
  }
  int ix0 = (int)ax, iy0 = (int)ay, ix1 = (int)bx, iy1 = (int)by;
  int dx = abs(ix1 - ix0), sx = ix0 < ix1 ? 1 : -1;
  int dy = -abs(iy1 - iy0), sy = iy0 < iy1 ? 1 : -1;
  int err = dx + dy;
  for (;;) {
    canvas_point(c, ix0, iy0, color);
    if (ix0 == ix1 && iy0 == iy1) break;
    int e2 = 2 * err;
    if (e2 >= dy) {
      err += dy;
      ix0 += sx;
    }
    if (e2 <= dx) {
      err += dx;
      iy0 += sy;
    }
  }
}

void canvas_fill_ellipse(Canvas *c, int x, int y, int w, int h,
                         uint16_t color) {
  if (w <= 0 || h <= 0) return;
  double cx = x + (w - 1) / 2.0, cy = y + (h - 1) / 2.0;
  double rx = w / 2.0, ry = h / 2.0;
  wide_t y0 = y < 0 ? 0 : y, y1 = (wide_t)y + h - 1;
  if (y1 >= c->h) y1 = c->h - 1;
  for (wide_t yy = y0; yy <= y1; yy++) {
    double ny = (yy - cy) / ry;
    double t = 1.0 - ny * ny;
    if (t < 0) continue;
    double half = rx * sqrt(t);
    wide_t xa = (wide_t)ceil(cx - half), xb = (wide_t)floor(cx + half);
    if (xb < xa) continue;
    hspan(c, xa, xb, yy, color);
  }
}

/* Insertion sort is quadratic, and with software doubles a 1000-point Pedal
 * picture spent seconds in it. Past a handful of crossings qsort wins. */
#define SORT_INSERTION_MAX 16

static int compare_doubles(const void *a, const void *b) {
  double x = *(const double *)a, y = *(const double *)b;
  return (x > y) - (x < y);
}

void canvas_fill_polygon(Canvas *c, const int *xy, int n, uint16_t color) {
  if (n < 3) return;
  /* An edge crosses a scanline at most once, so n slots always suffice. The
   * heap is only used for big polygons, to keep the task stack small. */
  double stack_xs[64];
  double *xs = stack_xs;
  if (n > 64) {
    xs = (double *)malloc((size_t)n * sizeof(double));
    if (!xs) return;
  }
  wide_t ymin = xy[1], ymax = xy[1];
  for (int i = 1; i < n; i++) {
    if (xy[2 * i + 1] < ymin) ymin = xy[2 * i + 1];
    if (xy[2 * i + 1] > ymax) ymax = xy[2 * i + 1];
  }
  if (ymin < 0) ymin = 0;
  if (ymax >= c->h) ymax = c->h - 1;
